def parse_name(msg, off):
    labels=[]
    jumped=False
    start=off
    while True:
        l=msg[off]
        if l==0:
            off+=1
            break
        if l & 0xC0 == 0xC0:
            ptr=((l & 0x3F)<<8)|msg[off+1]
            if not jumped:
                start=off+2
                jumped=True
            off=ptr
            continue
        off+=1
        labels.append(msg[off:off+l].decode('ascii'))
        off+=l
    return '.'.join(labels)+'.', (start if jumped else off)

def enc_name(name):
    if name=='.':
        return b'\\x00'
    name=name.rstrip('.')
    out=b''
    for part in name.split('.'):
        out += bytes([len(part)]) + part.encode('ascii')
    return out + b'\\x00'

def rr(name_wire, rtype, rclass, ttl, rdata):
    return name_wire + struct.pack('"'!HHIH'"', rtype, rclass, ttl, len(rdata)) + rdata

def a(ip):
