        l=msg[off]
        if l==0:
            off+=1
            break
        if l & 0xC0 == 0xC0:
            ptr=((l & 0x3F)<<8)|msg[off+1]
            sub,_=parse_name(msg, ptr)
            labels.append(sub.rstrip('.'))
            off+=2
            break
        off+=1
        labels.append(msg[off:off+l].decode('ascii'))
